args.sql:
SELECT h.housenum, h.residentcount, h.locregion, h.loczone, h.serviceplan 
FROM households h 
LIMIT 5;

SELECT s.serviceref, s.domestichelp, s.socsupport 
FROM service_types s 
WHERE TRIM(s.socsupport) = 'Yes';

SELECT DISTINCT p.dwelling_specs FROM properties p WHERE p.houselink IN (
    SELECT h.housenum FROM households h 
    JOIN service_types s ON h.serviceplan = s.serviceref 
    WHERE TRIM(s.socsupport) = 'Yes'
) LIMIT 5;

